import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TalkingIconProps = Record<string, any>;

const TalkingIcon: React.FC<TalkingIconProps> = ({
  backgroundColor = "#121212",
  transparentBackground = false,
  durationInSeconds = 8,
  figureColor = "#ffffff",
  mouthColor = "#121212",
  isTalking = true,
  talkSpeed = 6.5,
  bobbingIntensity = 0.5,
  showSpeechBubble = true,
  speechBubbleText = "yeah it's gonna be so easy i'm gonna get you that traffic",
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Sizing calculated for responsive center layout
  const s = Math.min(width, height);
  const size = s * 0.6;
  const headSize = size * 0.45;
  const bodyWidth = size * 0.75;
  const bodyHeight = size * 0.4;

  const time = frame / fps;

  // Entrance spring animation
  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });

  // Speech bubble animation with slight delay
  const bubbleScale = spring({
    fps,
    frame: frame - 15,
    config: { damping: 12, mass: 0.8 },
  });

  // Natural speech pattern simulation using combined sine waves
  const speechEnvelope = Math.max(0, Math.sin(time * 4) * Math.cos(time * 2.7) + 0.3);
  const mouthMotion = Math.abs(Math.sin(time * Math.PI * talkSpeed));
  const finalOpenness = isTalking ? mouthMotion * speechEnvelope : 0;

  // Mouth scaling interpolation
  const mouthScaleY = interpolate(finalOpenness, [0, 1], [0.1, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Slight horizontal mouth adjustment for realistic "O" shape simulation
  const mouthScaleX = interpolate(finalOpenness, [0, 1], [1, 0.75], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Breathing / Bobbing motion
  const breath = Math.sin(time * Math.PI * 0.6); // Cycles roughly every 3.3 seconds
  const bobbingPixels = size * 0.03 * bobbingIntensity;
  
  const bodyTranslateY = interpolate(breath, [-1, 1], [-bobbingPixels, bobbingPixels]);
  const headTranslateY = interpolate(breath, [-1, 1], [-bobbingPixels * 1.5, bobbingPixels * 1.5]);

  // Head micro-movements mimicking energetic talking
  const headTilt = isTalking ? interpolate(speechEnvelope * Math.sin(time * 5), [-1, 1], [-2, 2]) : 0;

  // Split text for word-by-word animation
  const words = speechBubbleText.split(/\s+/);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: size,
          height: size,
          transform: `scale(${entranceScale})`,
          transition: "none",
        }}
      >
        {/* SPEECH BUBBLE */}
        {showSpeechBubble && (
          <div
            style={{
              position: "absolute",
              bottom: size * 1.05,
              left: "50%",
              width: size * 1.4,
              maxWidth: width * 0.85,
              backgroundColor: figureColor,
              color: mouthColor,
              padding: size * 0.06,
              borderRadius: size * 0.08,
              transform: `translate(-50%, ${headTranslateY}px) scale(${bubbleScale})`,
              transformOrigin: "bottom center",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              textAlign: "center",
              fontSize: size * 0.045,
              fontWeight: 600,
              lineHeight: 1.4,
              boxShadow: `0 ${size * 0.02}px ${size * 0.05}px rgba(0,0,0,0.15)`,
              transition: "none",
              zIndex: 10,
            }}
          >
            <div
              style={{
                display: "inline-flex",
                flexWrap: "wrap",
                justifyContent: "center",
                gap: "0.25em",
                zIndex: 1,
              }}
            >
              {words.map((word, i) => {
                // Stagger appearance: Bubble starts at frame 15, words start at 25
                const wordDelay = 25 + i * 5; 
                
                const wordOpacity = interpolate(frame, [wordDelay, wordDelay + 5], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                });
                
                const wordScale = spring({
                  fps,
                  frame: frame - wordDelay,
                  config: { damping: 14, mass: 0.8 },
                });

                return (
                  <span
                    key={i}
                    style={{
                      opacity: wordOpacity,
                      transform: `scale(${wordScale})`,
                      display: "inline-block",
                      transition: "none",
                    }}
                  >
                    {word}
                  </span>
                );
              })}
            </div>
            
            {/* TAIL */}
            <svg
              style={{
                position: "absolute",
                bottom: -size * 0.045,
                left: "50%",
                transform: "translateX(-50%)",
                width: size * 0.08,
                height: size * 0.05,
                display: "block",
                transition: "none",
              }}
              viewBox="0 0 100 100"
              preserveAspectRatio="none"
            >
              <polygon points="0,0 100,0 50,100" fill={figureColor} />
            </svg>
          </div>
        )}

        {/* HEAD */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: "50%",
            width: headSize,
            height: headSize,
            backgroundColor: figureColor,
            borderRadius: "50%",
            transform: `translate(-50%, ${headTranslateY}px) rotate(${headTilt}deg)`,
            display: "flex",
            justifyContent: "center",
            alignItems: "flex-end",
            paddingBottom: headSize * 0.15,
            transformOrigin: "bottom center",
            boxShadow: `0 ${size * 0.02}px ${size * 0.05}px rgba(0,0,0,0.15)`,
            transition: "none",
            zIndex: 2,
          }}
        >
          {/* MOUTH */}
          <div
            style={{
              width: headSize * 0.35,
              height: headSize * 0.25,
              backgroundColor: mouthColor,
              borderRadius: headSize * 0.125,
              transform: `scale(${mouthScaleX}, ${mouthScaleY})`,
              transformOrigin: "center center",
              transition: "none",
            }}
          />
        </div>

        {/* BODY */}
        <div
          style={{
            position: "absolute",
            bottom: size * 0.05,
            left: "50%",
            width: bodyWidth,
            height: bodyHeight,
            backgroundColor: figureColor,
            borderTopLeftRadius: bodyWidth * 0.45,
            borderTopRightRadius: bodyWidth * 0.45,
            borderBottomLeftRadius: bodyWidth * 0.1,
            borderBottomRightRadius: bodyWidth * 0.1,
            transform: `translate(-50%, ${bodyTranslateY}px)`,
            boxShadow: `0 ${size * 0.02}px ${size * 0.05}px rgba(0,0,0,0.15)`,
            transition: "none",
            zIndex: 1,
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default TalkingIcon;